if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['setup'])){if(!csrf_ok())$err='درخواست نامعتبر';elseif(!$first)$err='قبلاً نصب شده';elseif(strlen((string)($_POST['password']??''))<10)$err='رمز حداقل ۱۰ کاراکتر';else{file_put_contents(PASS_FILE,password_hash((string)$_POST['password'],PASSWORD_DEFAULT),LOCK_EX);$_SESSION['admin']=true;header('Location: ./');exit;}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){$h=@file_get_contents(PASS_FILE);if(csrf_ok()&&$h&&password_verify((string)($_POST['password']??''),$h)){session_regenerate_id(true);$_SESSION['admin']=true;header('Location: ./');exit;}$err='رمز نادرست';}
